return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'jv_ID','project-id-version'=>'Babilim 1.2.2','pot-creation-date'=>'2026-11-09T07:54:24+00:00','po-revision-date'=>'2026-11-09T07:54:24+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Dikirim nalika sampeyan mencet Aktifake Babilim, lan maneh yen situs kudu ndhaftar ulang: URL situsmu, versi WordPress, PHP lan Babilim, basa situsmu lan basa sing digunakake ing situs kasebut, uga kunci publik sing digawe kanggo situs iki.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Dikirim ing saben pamriksan: dhaptar plugin lan tema sing wis diinstal bebarengan karo status Terjemahan Babilim sing wis diinstal kanggo kuwi, basa sing digunakake, lan kode diagnostik cekak.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Saben panjaluk nyakup URL situsmu, lan token akses situs bakal disertakake yen layanan butuh.','What Babilim sends to the service'=>'Data sing dikirim Babilim menyang layanan','Your site\'s URL'=>'URL situsmu','WordPress version'=>'Versi WordPress','PHP version'=>'Versi PHP','Babilim version'=>'Versi Babilim','Your site\'s language'=>'Basa situsmu','Languages in use on your site'=>'Basa sing digunakake ing situsmu','A public key for this site'=>'Kunci publik kanggo situs iki','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Kunci publik sing digawe kanggo situs iki, digunakake kanggo mbuktekake manawa panjaluk pancen asale saka situs iki. Mung separo publik sing dikirim; separo pribadi tetep ana ing situsmu.','Installed plugins and themes'=>'Plugin lan tema sing wis diinstal','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Kanggo saben plugin lan tema sing wis diinstal: jenenge (slug), versi, text domain, apa kadhaptar ing WordPress.org, lan basa sing wis kalebu. Kanggo saben Terjemahan Babilim sing wis sampeyan instal: versi pira, kapan pungkasan dipriksa, lan apa wis lulus pamriksan berkas.','Source files (only if you confirm an upload)'=>'Berkas sumber (mung yen sampeyan ngonfirmasi unggahan)','Diagnostic codes'=>'Kode diagnostik','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Nganti 20 kode diagnostik cekak (contone, berkas terjemahan sing gagal pamriksan), saben-saben karo plugin utawa tema, basa, lan wektu kedadeyane. Kode kasebut ora tau ngemot teks saka situsmu utawa teks terjemahan apa wae.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d situs ing jaringan iki disetel kanggo mbusak identitas Babilim-e nalika plugin dibusak. Lisensi mbayar sing ana ing situs kasebut banjur ora bisa dibalekake kanthi otomatis; sampeyan kudu ngubungi dhukungan Babilim ing %2$s. Kanggo njaga identitas, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pamrayogan Babilim situs kasebut, banjur nonaktifake maneh. Nonaktifake bae?' . "\0" . '%1$d situs ing jaringan iki disetel kanggo mbusak identitas Babilim-e nalika plugin dibusak. Lisensi mbayar sing ana ing situs-situs kasebut banjur ora bisa dibalekake kanthi otomatis; sampeyan kudu ngubungi dhukungan Babilim ing %2$s. Kanggo njaga identitas, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pamrayogan Babilim saben situs, banjur nonaktifake maneh. Nonaktifake bae?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s ora ana sing perlu ditindakake.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Pilih basané.','%d failed'=>'%d gagal' . "\0" . '%d gagal','%d not yet tried'=>'%d durung dicoba' . "\0" . '%d durung dicoba','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d laporan lagi ngenteni. "Tansah bagikan" lan "Aja dibagikan" ditrapake kanggo kabèh laporan kasebut.' . "\0" . '%d laporan lagi ngenteni. "Tansah bagikan" lan "Aja dibagikan" ditrapake kanggo kabèh laporan kasebut.','%d skipped'=>'%d dilewati' . "\0" . '%d dilewati','%d succeeded'=>'%d kasil' . "\0" . '%d kasil','%d to install'=>'%d kanggo diinstal' . "\0" . '%d kanggo diinstal','(a public key generated for this site)'=>'(kunci publik sing digawe kanggo situs iki)','(detected)'=>'(kadeteksi)','(generic codes and coordinates only)'=>'(mung kode umum lan koordinat)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Resik-resik dijeda ing %1$s: %2$s. Ora ana sing dibusak.','A file in the component could not be read, so it was not packaged.'=>'Ana berkas ing komponen sing ora bisa diwaca, mula ora dipaketake.','A host that serves only one PHP request at a time cannot complete this step.'=>'Host sing mung nglayani siji panyuwunan PHP ing sawijining wektu ora bisa ngrampungake langkah iki.','A part of the upload kept failing, so the upload was cancelled.'=>'Salah siji bagean unggahan terus gagal, mula unggahan dibatalake.','A translation cannot be requested for that locale on this site right now.'=>'Terjemahan ora bisa dijaluk kanggo locale kasebut ing situs iki saiki.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Panulisan indeks terjemahan bentrok karo panyuwunan liyane ing %1$s (%2$s) lan ora ditrapake; versi paling anyar disimpen.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Panulisan indeks terjemahan ing %1$s (%2$s) ora bisa rampung lan ora ditrapake (%3$s).','Account'=>'Akun','Add another language'=>'Tambah basa liyane','Advanced'=>'Lanjutan','All'=>'Kabeh','All free-plan slots for this site are used'=>'Kabeh slot paket gratis kanggo situs iki wis digunakake','All languages'=>'Kabeh basa','Already in WordPress core'=>'Wis ana ing inti WordPress','Already installed.'=>'Wis dipasang.','Always share'=>'Tansah bagikan','Another installation is running; try again in a moment.'=>'Ana instalasi liyane sing lagi mlaku; coba maneh sedhela.','Automatic installs'=>'Instalasi otomatis','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Instalasi otomatis saiki dipateni; aktifake maneh ing setelan yen sampeyan pengin.','Available'=>'Kasedhiya','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Terjemahan sing kasedhiya bisa diinstal kanthi sak klik, lan sing durung ana bisa dijaluk. Nalika instalasi otomatis diaktifake, terjemahan sing didhaptarake layanan minangka kasedhiya kanggo basa sing sampeyan kelola bakal diinstal nalika sinkronisasi kaping pindho saben dina.','Available · %s'=>'Kasedhiya · %s','Babilim'=>'Babilim','Babilim Settings'=>'Pamrayogan Babilim','Babilim adds translations for every language checked here.'=>'Babilim nambahake terjemahan kanggo saben basa sing dicentang ing kene.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ora bisa ngonfirmasi folder sementara ing njaba situs web, mula komponen ora dipaket lan ora ana sing diunggah. Temtokake BABILIM_TEMP_DIR ing wp-config.php minangka folder sing bisa ditulis ing njaba web root (tuladhane folder ing jejere, dudu ing njero, direktori publik situsmu), utawa njaluka folder kaya mangkono marang panyedhiya hostingmu.','Babilim could not finish checking this site.'=>'Babilim ora bisa ngrampungake pengecekan situs iki.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ora bisa rampung ngaktifake (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ora bisa ngrampungake verifikasi situs iki (layanan ora bisa nyambung bali). Pendaftaran dijeda.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ora bisa verifikasi situs iki, mula ora ana sing diundhuh utawa dipasang nganti verifikasi kasil.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ora bisa verifikasi situs iki, mula ora ana sing diundhuh utawa dipasang.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim njupuk terjemahan saka Layanan Babilim kanggo plugin lan tema ing situs iki sing durung duwe terjemahan kanggo basamu, lan nginstal sing dicakup paket layananmu.','Babilim has not been enabled for this site yet.'=>'Babilim durung diaktifake kanggo situs iki.','Babilim has not installed any translation for this language.'=>'Babilim during masang terjemahan apa wae kanggo basa iki.','Babilim hit an error. Share an error report?'=>'Babilim nemoni kesalahan. Bagikan laporan kesalahan?','Babilim installed %d translation automatically since your last visit.'=>'Babilim nginstal %d terjemahan kanthi otomatis wiwit kunjungan pungkasan sampeyan.' . "\0" . 'Babilim nginstal %d terjemahan kanthi otomatis wiwit kunjungan pungkasan sampeyan.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim dinonaktifake. Ora ana maneh sing dikirim; terjemahan sing wis dipasang tetep bisa digunakake.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim wis diaktifake: situs iki wis diverifikasi lan %d komponen ditemokake.' . "\0" . 'Babilim wis diaktifake: situs iki wis diverifikasi lan %d komponen ditemokake.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim lagi ngaktifake lan mriksa situs iki… (upaya pungkasan: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim lagi ngaktifake lan mriksa situs iki… Muat ulang kaca iki utawa enteni pamriksan terjadwal rampung.','Babilim is not enabled.'=>'Babilim ora diaktifake.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim disetel kanggo mbusak identitas situs iki nalika plugin dibusak. Lisensi mbayar sing ana ing situs iki banjur ora bisa dibalekake kanthi otomatis; sampeyan kudu ngubungi dhukungan Babilim ing %s. Kanggo njaga identitas, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pamrayogan Babilim, banjur nonaktifake maneh. Nonaktifake bae?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim kehabisan wektu kanggo langkah iki lan bakal nerusake ing pengecekan sabanjure.','Babilim settings'=>'Pamrayogan Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Sinkronisasi Babilim ditundha sauntara dening layanan (diwatesi lajune); bakal dicoba maneh sawise %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim wis dianyari nalika unggahan iki lagi ngenteni. Paket lawas wis dibuwang; mangga konfirmasi unggahan maneh.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim bakal ngunggah berkas-berkas iki saka %1$s (versi %2$s): saben berkas .php lan .js, saben berkas block.json, lan readme.txt, readme.md, style.css lan theme.json ing folder utamané. Berkas-berkas kuwi dienggo golèki teks sing kudu diterjemahaké lan ngenali plugin utawa tema kasebut.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ora kasedhiya: %s','Back'=>'Bali','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Tau tuku lisensi kanggo domain iki? Lebokna kode pemulihan sing sampeyan tampa nalika checkout.','Broken placeholder'=>'Placeholder rusak','Build'=>'Build','Built'=>'Wis dibangun','Bulk actions apply only to the selected language of each selected component.'=>'Tindakan massal mung ditrapake kanggo basa sing dipilih saka saben komponen sing dipilih.','Bulk actions apply to every matching language of each selected component.'=>'Tindakan massal ditrapake kanggo saben basa sing cocog saka saben komponen sing dipilih.','Bulk download:'=>'Unduhan massal:','Bulk request:'=>'Panjaluk massal:','Bulk update:'=>'Pembaruan massal:','Bundled with the plugin'=>'Kasedhiya bareng plugin','Bundled with the theme'=>'Kasedhiya bareng tema','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Kanthi ngeklik Aktifake, sampeyan setuju ngirim informasi sing kadhaptar ing ndhuwur menyang Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Kanthi nerusake, sampeyan ngonfirmasi yen sampeyan nduweni hak kanggo ngunggah komponen iki.','Cancel'=>'Batal','Category'=>'Kategori','Check again'=>'Priksa maneh','Check again now'=>'Priksa maneh saiki','Checkout is not available for this site right now.'=>'Checkout ora kasedhiya kanggo situs iki saiki.','Choose'=>'Pilih','Choose a category…'=>'Pilih kategori…','Choose a language'=>'Pilih basa','Choose a language…'=>'Pilih basa…','Clear filters'=>'Busak filter','Close'=>'Tutup','Component'=>'Komponen','Confirm'=>'Konfirmasi','Conflicting keys'=>'Kunci sing bentrok','Continue'=>'Terusaké','Continue next batch (%d left)'=>'Lanjutake batch sabanjuré (isih %d)','Continuing…'=>'Nerusake…','Could not back up %s before replacing it.'=>'Ora bisa nggawe serep %s sadurunge diganti.','Could not create the package archive.'=>'Arsip paket ora bisa digawe.','Could not determine active components; the existing merged index was left unchanged.'=>'Ora bisa nemtokake komponen aktif; indeks gabungan sing ana ora diowahi.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ora bisa nemtokake plugin/tema sing diinstal; sweep dilewati, ora ana sing dibusak.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ora bisa mbukak dhaptar lengkap locale WordPress.org saka layanan, mula ora ana basa liya sing bisa ditambahake saiki.','Could not move %s into place.'=>'Ora bisa mindhah %s menyang panggonane.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ora bisa mindhah indeks gabungan kanggo \'%s\' menyang panggonane; indeks sing disajikake sakdurunge (yen ana) wis dibusak, ora ditinggal setengah dianyari. Ora ana tambahan default-domain sing disajikake kanggo locale iki nganti rebuild sing sabanjure kasil.','Could not open zip: %s'=>'Ora bisa mbukak zip: %s','Could not prepare %s for rollback.'=>'Ora bisa nyiapake %s kanggo rollback.','Could not read %s back after moving it into place.'=>'Ora bisa maca maneh %s sawise dipindhah menyang panggonane.','Could not read: %s'=>'Ora bisa diwaca: %s','Could not restore the purchase: %s'=>'Ora bisa mulihake pembelian: %s','Could not show a new restore code: %s'=>'Ora bisa nampilake kode pemulihan anyar: %s','Could not stage %s'=>'Ora bisa nyiapake (stage) %s','Could not stage default/%s'=>'Ora bisa nyiapake (stage) default/%s','Could not start checkout: %s'=>'Ora bisa miwiti checkout: %s','Could not verify entry count for %s'=>'Ora bisa verifikasi jumlah entri kanggo %s','Could not write the downloaded package to disk.'=>'Ora bisa nulis paket sing wis diundhuh menyang disk.','Could not write the staged merged index.'=>'Ora bisa nulis indeks gabungan staged.','Current translation'=>'Terjemahan saiki','Custom overrides'=>'Timpa kustom','Danger zone'=>'Zona bebaya','Default supplement entry count mismatch.'=>'Jumlah entri suplemen default ora cocog.','Delete all Babilim data on uninstall'=>'Busak kabeh data Babilim nalika dicopot','Disable Babilim'=>'Nonaktifake Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Nonaktifake Babilim? Terjemahan sing wis diinstal bakal tetep disimpen, nanging ora ana pamriksan utawa unduhan maneh sing bakal mlaku.','Don\'t share'=>'Aja dibagikan','Download'=>'Undhuh','Downloaded and installed.'=>'Wis diundhuh lan dipasang.','Downloading…'=>'Ngundhuh…','Downloads: %1$d/%2$d (%3$s)'=>'Unduhan: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Kontribusi saben komponen kanggo tambahan default-domain bareng saben locale.','Enable Babilim'=>'Aktifake Babilim','Enabling…'=>'Lagi ngaktifake…','English (United States)'=>'Inggris (Amerika Serikat)','Entries'=>'Entri','Entry count mismatch for %s'=>'Jumlah entri ora cocog kanggo %s','Error reports'=>'Laporan kesalahan','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Saben locale sing digunakake ing situs iki (locale situs, paket basa sing diinstal, locale pangguna, lan sing sampeyan tambahake kanthi manual). Ora ana locale sing dianggep beda saka liyane.','Excluded'=>'Dikecualekake','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Berkas kanthi jeneng utawa ekstensi liyane ora kalebu, uga folder uploads, cache, logs, backup, data, vendor, node_modules lan languages, berkas sing didhelikake, utawa berkas sing jenengé cocog karo pola jeneng berkas sing lumrahé ngemot informasi rahasia (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Berkas kode isih bisa ngemot teks utawa data sing ora arep sampeyan bagèkaké; priksanen yèn sampeyan ora yakin. Layanan Babilim mbusak jinis berkas sing padha maneh nalika tekan.','Fills in missing translations for the plugins and themes already installed on your site.'=>'Nglengkapi terjemahan sing kurang kanggo plugin lan tema sing wis diinstal ing situsmu.','Free'=>'Gratis','Free-plan slots'=>'Slot paket gratis','General'=>'Umum','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Yen iki diaktifake, nyopot uga bakal mbusak identitas situs iki. Lisensi mbayar sing ana ing situs iki ora bisa dibalekake kanthi otomatis sawise iku; sampeyan kudu ngubungi dhukungan Babilim ing %s kanggo njaluk maneh.','Included'=>'Kalebu','Included in index'=>'Kalebu ing indeks','Install available translations automatically'=>'Instal terjemahan sing kasedhiya kanthi otomatis','Installed'=>'Wis dipasang','Installed translations are kept, but no further checks or downloads will run.'=>'Terjemahan sing wis diinstal tetep disimpen, nanging ora ana pamriksan utawa unduhan maneh sing bakal dijalanake.','Installed · %s'=>'Wis dipasang · %s','Installed · built for %1$s, this site has %2$s'=>'Wis diinstal · digawe kanggo %1$s, situs iki nganggo %2$s','Installed · built for %s'=>'Wis diinstal · digawe kanggo %s','Installed · built for %s, new version failed'=>'Wis dipasang · dibangun kanggo %s, versi anyar gagal','Installed · built for %s, new version scheduled'=>'Wis diinstal · digawe kanggo %s, versi anyar wis dijadwalake','Installed · built for %s, translating the new version…'=>'Wis diinstal · digawe kanggo %s, lagi nerjemahake versi anyar…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Wis diinstal · digawe kanggo %s; plugin utawa tema iki ora dilindhungi maneh dening paket layanan situs','Installed · built for a different version'=>'Wis diinstal · digawe kanggo versi beda','Installed · built for a different version, new version failed'=>'Wis dipasang · dibangun kanggo versi sing beda, versi anyar gagal','Installed · built for a different version, new version scheduled'=>'Wis diinstal · digawe kanggo versi beda, versi anyar wis dijadwalake','Installed · built for a different version, translating the new version…'=>'Wis diinstal · digawe kanggo versi beda, lagi nerjemahake versi anyar…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Wis diinstal · digawe kanggo versi sing beda; plugin utawa tema iki ora dilindhungi maneh dening paket layanan situs','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Iki disimpen déning panyedhia hosting layanan lan diproses model AI kanggo ngasilaké terjemahan.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Simpen penggantian terjemahan dhewe nalika mbusak kabeh utawa nyopot plugin iki.','Language'=>'Basa','Language:'=>'Basa:','Languages'=>'Basa-basa','Languages found on this site: %s.'=>'Basa sing ditemokake ing situs iki: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Resik-resik pungkasan ing %1$s: %2$d anyar ditandhani, %3$d berkas dibusak, %4$d rekaman disingkirake.','Maintenance'=>'Pangopènan','Maintenance status is not available right now.'=>'Status pangopènan ora kasedhiya saiki.','Manifest unavailable: %s'=>'Manifest ora kasedhiya: %s','Negation reversed'=>'Negasi dibalik','No'=>'Ora','No build is available to download for this locale.'=>'Ora ana build sing kasedhiya kanggo diunduh kanggo locale iki.','No cleanup has run yet.'=>'Durung ana resik-resik sing mlaku.','No components match these filters. %s'=>'Ora ana komponen sing cocog karo filter iki. %s','No components synced yet.'=>'Durung ana komponen sing disinkronake.','No installed translation matches.'=>'Ora ana terjemahan sing wis dipasang sing cocog.','No language is managed yet.'=>'Durung ana basa sing dikelola.','No pending challenge for this nonce.'=>'Ora ana tantangan sing isih ditundha kanggo nonce iki.','No pending challenge to verify.'=>'Ora ana tantangan sing nunggu verifikasi.','No plugins or themes found.'=>'Ora ana plugin utawa tema sing ditemokake.','No previous build to roll back to.'=>'Ora ana build sakdurunge kanggo rollback.','No record for %s'=>'Ora ana cathetan kanggo %s','No site id is on file to rotate a token for.'=>'Ora ana ID situs sing kasimpen kanggo ngrotasi token.','No — component inactive'=>'Ora — komponen ora aktif','No — component removed'=>'Ora — komponen wis dicopot','No — installed version differs from the active one'=>'Ora — versi sing diinstal beda karo sing aktif','Not a valid server_build_id: %s'=>'Dudu server_build_id sing sah: %s','Not covered by the free service plan'=>'Ora kalebu ing paket layanan gratis','Not installed'=>'Durung diinstal','Not registered yet'=>'Durung kadaftar','Not supported'=>'Ora didukung','Not verified'=>'Durung diverifikasi','Note (optional)'=>'Cathetan (opsional)','Nothing to choose.'=>'Ora ana sing bisa dipilih.','Nothing to confirm.'=>'Ora ana sing dikonfirmasi.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Mati kanthi baku: mbusak plugin tetep nyimpen identitas situs iki, supaya instal ulang bisa nggunakake maneh.','One or more served files no longer match the manifest.'=>'Siji utawa luwih berkas sing disajikake wis ora cocog maneh karo manifest.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Pembelian sepisan kanggo situs iki: %1$s %2$s. Kalebu kabeh nganyari terjemahan ing tembe. Pembayaran ditangani dening Paddle ing tab anyar.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Namung administrator jaringan sing bisa nindakake iki, amarga iki ngowahi berkas terjemahan sing dienggo bareng kabeh situs ing jaringan iki.','Only plugins and themes can be packaged.'=>'Namung plugin lan tema sing bisa dipaketake.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Namung nalika sampeyan ngonfirmasi unggahan kanggo plugin utawa tema sing ora ana ing WordPress.org: saben berkas .php lan .js, saben berkas block.json, lan readme.txt, readme.md, style.css lan theme.json ing folder utama komponen kasebut, awujud zip, sawisé berkas sing cocog karo pola jeneng berkas sing lumrahé ngemot informasi rahasia ora diklebokaké.','Open Babilim settings'=>'Bukak pamrayogan Babilim','Original language'=>'Basa asli','Original string'=>'String asli','Paid'=>'Mbayar','Partner'=>'Mitra','Please check that your site can be reached from the internet, then try again.'=>'Priksa manawa situs sampeyan bisa diakses saka internet, banjur coba maneh.','Please choose a category for this report.'=>'Mangga pilih kategori kanggo laporan iki.','Plugin'=>'Plugin','Plugin · %s'=>'Plugin · %s','Plugins'=>'Plugin','Preview'=>'Pratayang','Purchase restored. This site is now licensed.'=>'Pembelian wis dipulihake. Situs iki saiki wis duwe lisensi.','Re-parsed entry count did not match the built index.'=>'Jumlah entri sing diurai maneh ora cocog karo indeks sing dibangun.','Re-verify'=>'Verifikasi maneh','Rebuild index now'=>'Bangun maneh indeks saiki','Refusing to write outside the Babilim language-file directory.'=>'Ora gelem nulis ing njaba direktori berkas basa Babilim.','Registration response was missing required fields.'=>'Respons registrasi kurang kolom sing dibutuhake.','Registration restarted.'=>'Registrasi diwiwiti maneh.','Remove'=>'Busak','Remove everything Babilim installed'=>'Busak kabeh sing wis diinstal Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Busak kabeh sing wis diinstal Babilim? Iki bakal mbusak saben berkas basa sing wis diinstal Babilim kanggo saben plugin lan tema ing situs iki.','Remove the %2$s translation of %1$s from this site?'=>'Busak terjemahan %2$s saka %1$s saka situs iki?','Removed %d installed component.'=>'%d komponen sing diinstal wis dibusak.' . "\0" . '%d komponen sing diinstal wis dibusak.','Removed after a failed integrity check'=>'Dibusak sawise pamriksan integritas gagal','Removed.'=>'Wis dibusak.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Mbusak saben berkas basa sing wis diinstal Babilim kanggo saben plugin lan tema ing situs iki.','Report a problem'=>'Laporaké masalah','Report translation'=>'Laporake terjemahan','Request newer translation'=>'Njaluk terjemahan sing luwih anyar','Request translation'=>'Njaluk terjemahan','Requestable'=>'Bisa dijaluk','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Nyuwun terjemahan bakal nempatake plugin utawa tema iki ing salah siji slot paket layanan gratis kanggo situs iki (watese yaiku %1$d kanggo tema lan %2$d kanggo plugin), kajaba yen wis duwe slot. Slot tetep kepake, lan terjemahan sing gagal ora mbebasake slot kasebut.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Nyuwun terjemahan bakal nempatake plugin utawa tema iki ing salah siji slot paket layanan gratis kanggo situs iki, kajaba yen wis duwe slot. Slot tetep kepake, lan terjemahan sing gagal ora mbebasake slot kasebut.','Requesting…'=>'Njaluk…','Restart registration'=>'Miwiti maneh pendaftaran','Restore code'=>'Kode pemulihan','Restore purchase'=>'Pulihake tuku','Retry request'=>'Coba maneh panyuwunan','Roll back'=>'Balekake','Roll back and report'=>'Balekake lan laporake','Roll back and send report'=>'Wangsulake lan kirim laporan','Roll back the %2$s translation of %1$s to the previous build?'=>'Wangsulake terjemahan %2$s saka %1$s menyang build sakdurunge?','Rolled back and reported.'=>'Dibalekake lan dilaporake.','Rolled back to the previous build.'=>'Dibalekake menyang build sakdurunge.','Rolled back, but the report could not be sent: %s'=>'Dibalekake, nanging laporane ora bisa dikirim: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Rollback bakal nimpa \'%1$s\' (%2$s), sing saiki disajikake kanggo komponen liyane sing diinstal (%3$s); ora ana sing diowahi.','Rotate-token response was missing site_token.'=>'Wangsulan rotate-token ora ana site_token.','Save changes'=>'Simpen owahan','Scheduled, waiting to be processed'=>'Wis dijadwalake, ngenteni diproses','Search'=>'Telusuri','Search components'=>'Golèk komponèn','Search the installed translations'=>'Telusuri terjemahan sing wis dipasang','Select all'=>'Pilih kabeh','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Pilih komponen sing luwih sithik: paling akeh %1$d operasi saben proses (sampeyan milih %2$d).','Send report'=>'Kirim laporan','Service plan'=>'Paket layanan','Settings'=>'Pamrayogan','Share error reports'=>'Bagikan laporan kesalahan','Share this report'=>'Bagikan laporan iki','Show a new restore code'=>'Tampilake kode pemulihan anyar','Show the "Report translation" entry in the admin toolbar'=>'Tampilake entri "Report translation" ing bilah alat admin','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Sawetara teks saka komponen iki ditulis hard-coded dening pangriptane lan ora bisa diterjemahake nganggo paket basa.','Status'=>'Status','Status unknown'=>'Status ora dingerteni','String context'=>'Konteks string','Suggested translation'=>'Terjemahan sing disaranake','Supplementary translation index'=>'Indeks terjemahan tambahan','Supplementary translation index rebuilt.'=>'Indeks terjemahan tambahan wis dibangun maneh.','Supplementary translation maintenance'=>'Pangopènan terjemahan tambahan','Supplementary translations'=>'Terjemahan tambahan','Sweep aborted without orphaning anything: %s.'=>'Sweep dibatalake tanpa nggawe apa-apa dadi yatim: %s.','Sweep complete: %d file deleted.'=>'Resik-resik rampung: %d berkas dibusak.' . "\0" . 'Resik-resik rampung: %d berkas dibusak.','Sweep now'=>'Resiki saiki','Sync complete.'=>'Sinkronisasi rampung.','Thank you. Your report was sent.'=>'Matur nuwun. Laporanmu wis dikirim.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Komponen kasebut ora diinstal ing situs iki, mula terjemahan ora bisa dijaluk kanggo komponen kasebut.','That does not look like a restore code.'=>'Iki ora katon kaya kode pemulihan.','That is not a valid WordPress locale code. Nothing was saved.'=>'Iku dudu kode locale WordPress sing sah. Ora ana sing disimpen.','That is not a valid build identifier.'=>'Iku dudu pangenal build sing sah.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Layar unggah kasebut wis lawas: ana unggahan liyane sing wis disiapake wiwit iku. Ora ana sing dikirim. Priksa sing saiki saka Daftar terjemahan.','The change could not be recorded in the translation index; please try again.'=>'Owah-owahan ora bisa dicathet ing indeks terjemahan; coba maneh.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Resik-resik wis mlaku, nanging sawetara owah-owahane ora bisa dicathet ing indeks terjemahan; resik-resik sabanjure bakal nyoba maneh.','The component has no files that can be uploaded.'=>'Komponen iki ora duwé berkas sing bisa diunggah.','The component is not inside the plugins or themes directory.'=>'Komponen ora ana ing direktori plugin utawa tema.','The component\'s main file was not found.'=>'Berkas utama komponen ora ditemokake.','The download response was missing a usable location.'=>'Wangsulan undhuhan ora ana lokasi sing bisa digunakake.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Entri iki mbukak panel kanggo nggoleki terjemahan sing diinstal Babilim ing situs iki lan nglaporake salah sijine.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Kolom "%1$s" dawa banget: isine %2$d karakter lan watese %3$d. Ora ana sing dikirim; mangga cekakake lan coba maneh.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Paket layanan gratis menehi saben situs jumlah slot sing winates kanggo plugin lan tema; slot sing digunakake ditampilake ing Setelan sawise sampeyan ngaktifake Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Domain sing diwenehake \'%1$s\' ora cocog karo slug manifest paket \'%2$s\' utawa text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Indeks gabungan kanggo \'%s\' wis dibangun maneh, nanging indeks terjemahan ora bisa nyathet; pambangunan maneh sabanjure bakal nyoba maneh.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Teks asli lan terjemahan sing digawé saka kuwi bakal diwènèhaké menyang situs liya sing masang versi sing padha.','The package declares no main translation file.'=>'Paket ora nyatakake berkas terjemahan utama.','The package has no %s for its own text domain.'=>'Paket ora duwe %s kanggo text domain dhewe.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Kind \'%1$s\' ing manifest paket ora cocog karo kind sing dijaluk \'%2$s\'.','The package produced no servable main translation file.'=>'Paket ora ngasilake berkas terjemahan utama sing bisa disajikake.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Text domain paket \'%1$s\' ora cocog karo salinan komponen ing situs iki (\'%2$s\'), mula ora diinstal.','The packaged component could not be read.'=>'Komponen sing wis dipaketake ora bisa diwaca.','The registration challenge is not in the expected form.'=>'Tantangan registrasi ora ana ing wujud sing dikarepake.','The report could not be sent.'=>'Laporan ora bisa dikirim.','The search could not be completed.'=>'Panelusuran ora bisa rampung.','The service asked this site to wait before syncing again.'=>'Layanan njaluk situs iki ngenteni sadurunge sinkronisasi maneh.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Layanan ora bisa nyambung menyang situs sampeyan. Firewall, plugin keamanan utawa aturan host kayane ngeblokir panyuwunan; mangga ijinake panyuwunan menyang /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Tawaran unggah saka layanan ora lengkap.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Text domain \'%1$s\' (%2$s) wis disajikake kanggo komponen liyane sing diinstal (%3$s); ora ana sing diinstal.','The upload is kept until you ask Babilim to delete it.'=>'Unggahan disimpen nganti Panjenengan njaluk Babilim mbusaké.','Theme'=>'Tema','Theme · %s'=>'Tema · %s','Themes'=>'Tema','There is no upload in progress.'=>'Ora ana unggahan sing lagi mlaku.','There is no upload waiting for confirmation.'=>'Ora ana unggahan sing nunggu konfirmasi.','These are the languages this site uses. You can change them in %s.'=>'Iki basa-basa sing digunakake situs iki. Panjenengan bisa ngowahi ing %s.','These fields will be sent:'=>'Kolom-kolom iki bakal dikirim:','This build is not one this site currently knows about for this component/locale.'=>'Build iki dudu build sing saiki dikenal situs iki kanggo komponen/locale iki.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Komponen iki ora nyatakake nomer versi, mula terjemahan ora bisa dijaluk kanggo komponen iki.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Komponen iki luwih gedhe tinimbang sing ditampa layanan, mula ora bisa diunggah.','This component was already uploaded. Babilim is checking it now.'=>'Komponen iki wis diunggah. Babilim lagi mriksa saiki.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Nomer versi komponen iki luwih saka %d karakter, sing ora bisa ditangani Babilim, mula terjemahan ora bisa dijaluk kanggo komponen iki.','This issues a new restore code and the previous one stops working. Continue?'=>'Iki bakal nerbitake kode pemulihan anyar lan kode sing sadurunge ora bisa digunakake maneh. Terusake?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Jaringan iki duwe situs sing kakehan kanggo dipriksa siji-siji, lan sawetara mbok menawa disetel kanggo mbusak identitas Babilim nalika plugin dibusak. Lisensi mbayar sing ana ing situs kuwi banjur ora bisa dibalekake kanthi otomatis; sampeyan kudu ngubungi dhukungan Babilim ing %s. Kanggo njaga identitas, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pamrayogan Babilim saben situs, banjur nonaktifake maneh. Nonaktifake bae?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Versi plugin iki dhewe, supaya layanan bisa ngandhani sampeyan kanggo nganyari yen wis kadaluwarsa banget kanggo komunikasi.','This report does not name a valid plugin or theme and locale.'=>'Laporan iki ora nyebutake Jeneng plugin utawa tema lan locale sing sah.','This report does not name an installed string.'=>'Laporan iki ora nyebutake jeneng string sing wis dipasang.','This report is missing a valid build to report against.'=>'Laporan iki ora duwe build sing sah kanggo dilaporake.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Laporan iki bakal dipostèkaké sacara umum ing GitHub lan bisa disimpen déning pihak katelu.','This restore code was not recognised for this site.'=>'Kode pemulihan iki ora dikenali kanggo situs iki.','This site already has an active registration that can no longer be recovered automatically.'=>'Situs iki wis nduweni pendaftaran aktif sing ora bisa dipulihake kanthi otomatis maneh.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Situs iki nduwé %1$d komponen ing %2$d basa, sing mbutuhake %3$d batch pamriksan; Babilim mung bisa nangani paling akeh %4$d saben proses. Kurangi basa sing dikelola ing Setelan utawa nonaktifake plugin lan tema sing ora digunakake, banjur pencet Priksa maneh saiki.','This site has no purchase to show a code for.'=>'Situs iki ora duwe pembelian sing bisa dituduhake kodene.','This site is already licensed. Reload the page.'=>'Situs iki wis nduweni lisensi. Muat ulang kaca.','This site is not registered with Babilim yet.'=>'Situs iki durung didaftarake ing Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Situs iki ngluwihi ukuran sing ditampa layanan sajrone siji sinkronisasi, mula sawetara item ora kalebu: %1$d komponen lan %2$d locale.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Situs iki dadi bagéan saka jaringan multisitus, sing ora nginstal terjemahan anyar kanthi otomatis. Terjemahan sing wis diinstal isih dianyari.','This site is verified.'=>'Situs iki wis diverifikasi.','This site must be verified first.'=>'Situs iki kudu diverifikasi dhisik.','This site\'s URL, so the service can verify you own it.'=>'URL situs iki, supaya layanan bisa mbuktekake yen sampeyan sing duwe.','This site\'s address is too long for Babilim to register.'=>'Alamat situs iki dawa banget kanggo diregistrasi dening Babilim.','This site\'s configured locale.'=>'Locale sing dikonfigurasi ing situs iki.','This site\'s locale code is not one Babilim can register.'=>'Kode locale situs iki dudu sing bisa didaftarake dening Babilim.','This string can\'t be reported from this site.'=>'String iki ora bisa dilaporake saka situs iki.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'String iki ora kalebu ing terjemahan sing dipasang ing situs iki. Telusuri maneh lan pilih saka dhaptar.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Terjemahan iki wis dianyari wiwit sampeyan nelusuri. Telusuri maneh lan pilih string saka dhaptar anyar.','To translate this component, Babilim needs its source.'=>'Kanggo nerjemahake komponen iki, Babilim mbutuhake sumbere.','Too many attempts. Try again tomorrow.'=>'Kakehan upaya. Cobanen maneh sesuk.','Too many reports today. Try again tomorrow.'=>'Laporan dina iki kakehan. Coba maneh sesuk.','Too many requests.'=>'Panyuwunan kakehan.','Toolbar'=>'Bilah alat','Translating…'=>'Lagi nerjemahake…','Translation does not load'=>'Terjemahan ora kemuat','Translation failed'=>'Terjemahan gagal','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Berkas terjemahan sing sampeyan selehake ing %s tansah luwih utama tinimbang sing saka Babilim. Berkas kasebut disimpen kajaba sampeyan mbusak centhange.','Translation requested.'=>'Terjemahan wis dijaluk.','Translations'=>'Terjemahan','Type'=>'Jinis','Type at least 2 characters to search.'=>'Ketik paling ora 2 aksara kanggo nggoleki.','Unexpected HTTP %d response.'=>'Respons HTTP %d sing ora dikarepake.','Uninstall'=>'Nyopot','Unknown kind: %s'=>'Kind ora dikenal: %s','Unsafe domain: %s'=>'Domain ora aman: %s','Unsafe locale: %s'=>'Locale ora aman: %s','Unsafe slug: %s'=>'Slug ora aman: %s','Unsafe text_domain: %s'=>'text_domain ora aman: %s','Update'=>'Nganyari','Update available'=>'Ana versi anyar sing kasedhiya','Updates'=>'Pembaruan','Updating…'=>'Nganyari…','Upgrade this site'=>'Upgrade situs iki','Upload and request'=>'Unggah lan njaluk','Upload cancelled.'=>'Unggahan dibatalake.','Upload complete — translation requested.'=>'Unggahan rampung — terjemahan wis dijaluk.','Upload expired before it finished'=>'Unggahan kadaluwarsa sadurunge rampung','Upload in progress — continue or cancel'=>'Unggahan lagi mlaku — terusake utawa batalake','Upload this component?'=>'Unggah komponen iki?','Upload was not accepted'=>'Unggahan ora ditampa','Uploading'=>'Lagi ngunggah','Uploading part %1$d of %2$d…'=>'Lagi ngunggah bagéan %1$d saka %2$d…','Uploading…'=>'Lagi ngunggah…','Verified'=>'Wis diverifikasi','Verify response was missing site_token.'=>'Wangsulan verifikasi ora ana site_token.','Version %s'=>'Versi %s','What is sent when you enable Babilim'=>'Apa sing dikirim nalika sampeyan ngaktifake Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Nalika ana sing gagal ing Babilim, kirimna laporan kesalahan menyang layanan Babilim supaya bisa diterbitake minangka isu umum ing GitHub. Laporan dikirim minangka saka situs iki, kanthi autentikasi sing padha karo saben panyuwunan liyane menyang layanan Babilim. Layanan kasebut mung nerbitake kode kesalahan lan versi minangka isu umum ing GitHub; isu umum kasebut ora ngandhut alamat situs, isi, utawa path berkas. Mati kanthi baku.','Where you saw this (optional)'=>'Ing ngendi sampeyan ndeleng iki (opsional)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Nalika iki diaktifake, terjemahan sing didhaptarake layanan minangka kasedhiya kanggo basa sing sampeyan kelola bakal diinstal nalika sinkronisasi kaping pindho saben dina.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Salah kanggo konteks iki','Wrong meaning'=>'Teges salah','Wrong plural form'=>'Wangun jamak sing salah','Wrong term'=>'Istilah salah','Yes'=>'Ya','You are not allowed to do this.'=>'Sampeyan ora diidini nindakake iki.','Your PHP version, for compatibility.'=>'Versi PHP sampeyan, kanggo kompatibilitas.','Your WordPress version, to serve compatible translation files.'=>'Versi WordPress sampeyan, kanggo nyedhiyakake berkas terjemahan sing cocog.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Kode pemulihan anyar sampeyan: %s. Simpenen ing panggonan sing aman — kode sadurunge ora bisa digunakake maneh.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Laporanmu diproses kanthi otomatis déning model AI lan bisa nambah kualitas terjemahan iki kanggo situs liyane.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Situs sampeyan mangsuli, nanging ora kaya sing dikarepake. REST API bisa wae ditulis ulang dening plugin liyane, utawa endpoint kuwi di-cache; mangga kecualiake /wp-json/babilim/v1/challenge saka caching lan penulisan ulang.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Situs sampeyan suwe banget anggone mangsuli. Coba maneh mengko, lan priksa manawa host sampeyan ora alon banget utawa kebebanan.','Zip has no manifest.json.'=>'Zip ora duwe manifest.json.','Zip is missing expected default file: %s'=>'Zip ora ana berkas default sing dikarepake: %s','Zip is missing expected file: %s'=>'Zip ora ana berkas sing dikarepake: %s','_manifest.json has an unexpected structure'=>'_manifest.json nduweni struktur sing ora dikarepake','could not read _manifest.json: %s'=>'ora bisa maca _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest ilang utawa duwe \'%s\' sing ora sah.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ing expected_manifest dudu build id sing sah.','failed to parse _manifest.json: %s'=>'gagal ngurai _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'bakal gawe yatim %1$d saka %2$d komponen sing dikelola (luwih saka separo)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'bakal gawe yatim saben komponen %1$s sing dikelola (%2$d saka %2$d)','l10n.php entry count mismatch for %s'=>'Cacahe entri l10n.php ora cocog kanggo %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json duwe \'default_domain_entries\' sing ora sah.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json duwe \'default_domain_files\' sing ora sah.','manifest.json in the zip is not valid JSON.'=>'manifest.json ing zip dudu JSON sing sah.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json ilang utawa duwe \'%s\' sing ora sah.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json ilang utawa duwe \'build_no\' sing ora sah.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json ilang utawa duwe \'entries\' sing ora sah.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json ilang utawa duwe \'extra_domains\' sing ora sah.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json ilang utawa duwe \'files\' sing ora sah.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' ing manifest.json ora cocog karo nilai sing diarepake.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' ing manifest.json dudu string versi sing sah.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' ing manifest.json kudu \'plugin\' utawa \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ing manifest.json dudu build id sing sah.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' ing manifest.json kudu \'published\'.','nonce must be a hexadecimal string.'=>'nonce kudu string heksadesimal.','per day'=>'saben dina','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256 ora cocog kanggo %s','sha256 mismatch for default/%s'=>'sha256 ora cocog kanggo default/%s','component kind in the sweep brake messageplugin'=>'plugin','component kind in the sweep brake messagetheme'=>'tema','problem report categoryOther'=>'Liyane','translation statusAvailable'=>'Kasedhiya','translation statusInstalled'=>'Wis diinstal','Babilim translation turned off.'=>'Terjemahan Babilim wis dipateni.','Stop using Babilim translation'=>'Mandheg nggunakake terjemahan Babilim','Use Babilim translation'=>'Gunakake terjemahan Babilim','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Mandheg nggunakake terjemahan Babilim saka %1$s (%2$s)? WordPress bakal nggunakake terjemahan bawaan tema utawa terjemahan WordPress.org. Sampeyan bisa bali menyang terjemahan Babilim kapan wae.','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Mandheg nggunakake terjemahan Babilim saka %1$s (%2$s)? WordPress bakal nggunakake terjemahan bawaan plugin utawa terjemahan WordPress.org. Sampeyan bisa bali menyang terjemahan Babilim kapan wae.']];